function feedItem(f){ return `<div class="item${isHi(f)?' hi':''}"><div class="d">${esc(f.date)}</div><div><div class="meta">${sev(f.severity)}<span>${esc(f.category)}</span><span>·</span><span>${esc(f.entity)}</span></div><h4>${esc(f.title)}</h4><p>${esc(f.summary)}</p>${f.implication?`<div class="imp"><b>So what:</b> ${esc(f.implication)}</div>`:''}<div class="meta" style="margin-top:4px">${link(f.url,f.source||'source')}</div></div></div>`; }

/* ---------------- MARKETS ---------------- */
function marketChart(id, tickers, mode='rebased'){
  const S=D.market.series; const labels=S.GOTO.points.map(p=>p[0]);
  const ds=tickers.filter(t=>S[t]).map((t,i)=>{ const pts=S[t].points; const base=pts[0][1]; const m=Object.fromEntries(pts);
    return {label:t, data:labels.map(l=>m[l]==null?null:(mode==='rebased'? m[l]/base*100 : m[l])), borderColor:PAL[i%PAL.length], backgroundColor:PAL[i%PAL.length], borderWidth:t==='GOTO'?2.6:1.6, pointRadius:0, tension:.25, spanGaps:true}; });
  chart(id,{type:'line',data:{labels,datasets:ds},options:baseOpts({plugins:{legend:{labels:{color:css('--muted'),boxWidth:10}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${fmt(c.parsed.y,1)}`}}}})});
}
function vMarketsBaseline(){
  const sn=D.market.snapshot, S=D.market.series;
  const tk=Object.keys(S);
  const rows=tk.map(t=>{const x=sn[t]||{}; const lid={'GOTO':'goto','GRAB':'grab','SE':'shopee','BUKA':null,'UBER':'tk_UBER','DASH':'tk_DASH','MEITUAN':'tk_MEITUAN','NU':null,'JKSE':null}[t];
    return `<tr><td><div style="display:flex;gap:8px;align-items:center">${logo(lid||'x_'+t,S[t].name,1)}<div><b>${t}</b><div class="note">${esc(S[t].name)}</div></div></div></td><td class="r mono">${fmt(x.price,x.price<100?2:0)} ${esc(S[t].ccy)}</td><td class="r mono">${esc(x.date||'–')}</td><td class="r mono ${x.m1_pct<0?'down':'up'}">${fmt(x.m1_pct,1)}%</td><td class="r mono ${x.ytd_pct<0?'down':'up'}">${fmt(x.ytd_pct,1)}%</td><td class="r mono">${fmt(x.lo52,x.lo52<100?2:0)} – ${fmt(x.hi52,x.hi52<100?2:0)}</td><td class="r mono">${x.mcap_usd_mn?fmt(x.mcap_usd_mn/1000,1)+'bn':'–'}</td><td>${tvb(t)}</td></tr>`;}).join('');
  $('#v-markets').innerHTML=`
  <div class="card"><h3>Interactive chart · TradingView engine <small id="lwm">month-end closes Jan-24 to Oct-26 · drag to pan, scroll to zoom</small></h3>
   <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px">
    <div class="chips" id="tkc" style="margin:0">${tk.map(t=>`<button class="chip ${['GOTO','GRAB','SE','BUKA','JKSE'].includes(t)?'on':''}" data-t="${t}" type="button">${t}</button>`).join('')}</div>
    <div class="toggle" id="lmode"><button type="button" data-m="rebased" class="on">Compare (rebased)</button><button type="button" data-m="price">Price · focus ticker</button></div>
    <span style="margin-left:auto;display:flex;gap:6px"><a class="tvb" id="tvlive" target="_blank" rel="noopener">Open GOTO live ↗</a><button class="btn" id="tvtry" type="button">Retry live widget</button></span></div>
   <div id="tvw" style="display:none;height:520px;margin-bottom:12px"></div>
   <div id="lwc" style="height:400px;position:relative"></div>
   <p class="note" id="lwnote" style="margin:8px 0 0">Chart drawn with TradingView Lightweight Charts™ inside this page. GOTO was pinned at the IDX Rp50 floor May-Sep 2026; the floor was cut to Rp1 on 28 Sep. Sources: digrin, Yahoo Finance, StockAnalysis (see notes).</p></div>
  <div class="card" style="margin-top:14px"><h3>Peer snapshot <small>as of ${esc(D.market.as_of)}</small></h3><div class="tw"><table><thead><tr><th>Company</th><th class="r">Price</th><th class="r">Date</th><th class="r">1M</th><th class="r">YTD</th><th class="r">52-week range</th><th class="r">Mkt cap (US$)</th><th>Real-time</th></tr></thead><tbody>${rows}</tbody></table></div>
  <p class="note">${(D.market.notes||[]).slice(0,4).map(esc).join(' · ')}</p></div>`;
  let focus='GOTO', lmode='rebased', lw=null;
  const sym=t=>D.tv[t]||'IDX:GOTO';
  const setLive=()=>{const a=$('#tvlive'); a.href=tvu(sym(focus)); a.textContent=`Open ${focus} live ↗`;};
  const draw=()=>{ const on=[...document.querySelectorAll('#tkc .chip.on[data-t]')].map(b=>b.dataset.t); if(!on.includes(focus)&&on.length) focus=on[0]; setLive();
    const LC=window.LightweightCharts, box=$('#lwc');
    if(!LC){ box.innerHTML='<canvas id="c-mk"></canvas>'; marketChart('c-mk',on,lmode); return; }
    if(lw){ lw.remove(); lw=null; } box.innerHTML='';
    const ink=css('--muted'), line=css('--line');
    lw=LC.createChart(box,{autoSize:true,layout:{background:{type:'solid',color:'transparent'},textColor:ink,fontFamily:"'Instrument Sans',system-ui,sans-serif",attributionLogo:true},
      grid:{vertLines:{color:line},horzLines:{color:line}},rightPriceScale:{borderColor:line},timeScale:{borderColor:line,timeVisible:false},crosshair:{mode:0},localization:{locale:'en-US',priceFormatter:v=>lmode==='rebased'?v.toFixed(0):(Math.abs(v)<100?v.toFixed(2):Math.round(v).toLocaleString('en-US'))}});
    const S=D.market.series;
    const pts=t=>S[t].points.map((p,i,a)=>({time:(i===a.length-1&&D.market.snapshot[t]?.date&&D.market.snapshot[t].date.startsWith(p[0]))?D.market.snapshot[t].date:p[0]+'-28',value:p[1]}));
    if(lmode==='price'){ const c=css('--accent'); const s=lw.addSeries(LC.AreaSeries,{lineColor:c,topColor:c+'55',bottomColor:c+'05',lineWidth:2,title:focus+' · '+S[focus].ccy}); s.setData(pts(focus));
      $('#lwm').textContent=`${S[focus].name} · ${S[focus].ccy} · month-end closes`; }
    else { on.forEach((t,i)=>{ const P=pts(t), b=P[0].value; const s=lw.addSeries(LC.LineSeries,{color:PAL[i%PAL.length],lineWidth:t==='GOTO'?3:2,title:t,priceLineVisible:false}); s.setData(P.map(p=>({time:p.time,value:p.value/b*100}))); });
      $('#lwm').textContent='Rebased Jan-24 = 100 · drag to pan, scroll to zoom'; }
    lw.timeScale().fitContent(); };
  $('#tkc').onclick=e=>{const b=e.target.closest('.chip'); if(!b) return; if(lmode==='price'){ [...$('#tkc').children].forEach(x=>x.classList.toggle('on',x===b)); focus=b.dataset.t; } else { b.classList.toggle('on'); if(b.classList.contains('on')) focus=b.dataset.t; } draw();};
  $('#lmode').onclick=e=>{const b=e.target.closest('button'); if(!b) return; lmode=b.dataset.m; [...$('#lmode').children].forEach(x=>x.classList.toggle('on',x===b)); if(lmode==='price') [...$('#tkc').children].forEach(x=>x.classList.toggle('on',x.dataset.t===focus)); draw();};
  $('#tvtry').onclick=()=>{ const w=$('#tvw'); w.style.display='block'; let blocked=false;
    const onV=ev=>{ if(String(ev.blockedURI||'').includes('tradingview')){ blocked=true; w.innerHTML=`<div class="decision" style="margin:0"><b>Live TradingView widget blocked by the hosting sandbox</b><p>This hosted page cannot load third-party frames, so the chart below uses TradingView\'s charting engine with stored closes. For streaming prices open the downloadable live-charts file in your browser, or <a href="${tvu(sym(focus))}" target="_blank" rel="noopener">open ${esc(focus)} live on TradingView ↗</a>.</p></div>`; w.style.height='auto'; } };
    document.addEventListener('securitypolicyviolation',onV,{once:false});
    const dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme: dark)').matches);
    w.innerHTML=`<iframe title="TradingView live chart ${esc(focus)}" src="https://s.tradingview.com/widgetembed/?symbol=${encodeURIComponent(sym(focus))}&interval=D&theme=${dark?'dark':'light'}&style=1&timezone=Asia%2FJakarta&locale=en&hide_side_toolbar=0" style="width:100%;height:100%;border:1px solid var(--line);border-radius:10px" allowfullscreen></iframe>`;
    setTimeout(()=>document.removeEventListener('securitypolicyviolation',onV),8000); };
  draw(); $('#tvtry').onclick();
}

