/* ---------------- SYSTEM ---------------- */
function vSysBaseline(){
  const steps=[['01 · SENSE','Collect','IR sites, IDX disclosures, regulators, press, broker PDFs, market data, macro releases.'],['02 · RESOLVE','Link to the map','Match each item to an ecosystem entity, business line and valuation driver.'],['03 · VERIFY','Check','Cross-source checks; conflicting figures flagged; unverified relationships labelled.'],['04 · ASSESS','So what','Severity, direction and which model input moves (take rate, GTV, WACC, share count).'],['05 · DECIDE','Recommend','Draft decision, alternatives and the strongest counter-argument; analyst owns the call.'],['06 · ACT','Escalate','Weekly brief, diligence requests, owners and triggers; re-run models.']];
  $('#v-system').innerHTML=`<div class="flow">${steps.map(s=>`<div class="step"><span class="k">${s[0]}</span><b>${s[1]}</b><small>${s[2]}</small></div>`).join('')}</div>
  <div class="grid g2" style="margin-top:14px">
   <div class="card"><h3>Agents in the loop</h3><table><tbody>
    <tr><td><b>Market & macro agent</b></td><td class="note">Prices, peers, BI/BPS/OJK releases; refreshes charts and the WACC inputs.</td></tr>
    <tr><td><b>Disclosure agent</b></td><td class="note">GoTo, Grab, Sea, Bank Jago IR and IDX filings; extracts statements line by line and checks they tie.</td></tr>
    <tr><td><b>Ecosystem & portfolio agent</b></td><td class="note">News on every mapped company; updates risk flags and triggers.</td></tr>
    <tr><td><b>Research librarian</b></td><td class="note">Collects broker, macro and M&A reports; summarises and versions them (what changed vs last note).</td></tr>
    <tr><td><b>Deal-sourcing agent</b></td><td class="note">Screens targets against the mandate; checks duplication with existing GoTo capability; drafts diligence questions.</td></tr>
    <tr><td><b>Valuation agent</b></td><td class="note">Deterministic models (DCF, comps, SOTP); recomputes when an input changes and logs the delta.</td></tr></tbody></table></div>
   <div class="card"><h3>Guardrails</h3><ul style="margin:0;padding-left:18px"><li>Every number carries a date and a source; reported facts, assumptions and calculations are kept apart.</li><li>Models are deterministic spreadsheets; agents propose input changes, the analyst approves.</li><li>Conflicting sources are shown, not averaged (e.g. 2Q26 profit reported as Rp252bn vs Rp349.5bn attributable).</li><li>Unverified relationships are labelled (e.g. Bintang Kecil, Kopi Kenangan).</li><li>Confidential deal data stays out of public tools.</li></ul>
   <h3 style="margin-top:14px">This run</h3><p class="note" style="margin:0">13 Oct 2026: ${D.feed.length} signals, ${D.research.length} research items, ${E.length} entities, ${D.macro.indicators.length} indicators, ${D.deals.length}+${D.global.length} sourcing candidates, 10 quarterly filings (1Q24-2Q26) extracted and tied.</p></div>
  </div>`;
}

