function replaceViewText(root,from,to){const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walk.nextNode()){if(n.nodeValue.includes(from))n.nodeValue=n.nodeValue.replaceAll(from,to)}}
