function restructurePortfolio(){const sec=$('#v-portfolio'),intro=sec.firstElementChild,metrics=sec.querySelector('.grid.g3'),hub=sec.querySelector('.capital-hub'),map=sec.querySelector('.capital-grid'),values=sec.querySelector('.grid.g2'),toolbar=$('#holdingSearch').closest('.feed-toolbar'),table=$('#holdingRows').closest('.card'),limits=table.nextElementSibling,updates=sec.lastElementChild;const tabs=document.createElement('nav');tabs.className='position-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Portfolio workspace views');tabs.innerHTML=[['map','Capital routes'],['register','Position register · '+D.portfolioRegister.records.length],['updates','Updates & risk']].map(([id,label],i)=>`<button role="tab" data-position-tab="${id}" aria-controls="position-${id}" aria-selected="${!i}">${label}</button>`).join('');const panels={};for(const [id,label] of [['map','Capital routes'],['register','Position register'],['updates','Updates & risk']]){const p=document.createElement('section');p.id='position-'+id;p.setAttribute('role','tabpanel');p.setAttribute('aria-label',label);p.hidden=id!=='map';panels[id]=p}panels.map.append(hub,map);const strategic=document.createElement('div');strategic.className='strategic-refresh';strategic.innerHTML=`<div><b>Strategic equity to refresh</b><p class="note">Historical links remain visible; current percentages and values require evidence.</p></div>${['electrum','anteraja','pathao'].map(id=>`<button class="btn company-link" data-ent="${id}">${logo(id,byId[id].name,1)}${esc(byId[id].name.split('(')[0])} ↗</button>`).join('')}`;panels.map.append(strategic,values);panels.register.append(toolbar,table,limits);panels.updates.innerHTML=`<div class="decision"><b>Follow the news through the actual position</b><p>Operating developments and historical holdings have different economic meaning. Open a company to inspect its reviewed updates, RSS leads, current-position gaps and diligence steps.</p></div>`;panels.updates.append(updates);sec.replaceChildren(intro,metrics,tabs,...Object.values(panels));table.querySelector('thead tr').innerHTML='<th>Company / workspace</th><th>Position & economics</th><th>Status / evidence</th><th>Latest reviewed signal</th>';$('#holdingGroup').insertAdjacentHTML('beforeend','<option value="legal">Full legal inventory · 62 entities</option>');toolbar.insertAdjacentHTML('beforeend','<select class="search" id="holdingStatus" aria-label="Filter position status"><option value="all">All statuses</option><option value="current">Current disclosed entities</option><option value="historical">Historical / reported exits</option><option value="pending">Needs verification</option></select>');const draw=()=>{const group=$('#holdingGroup').value,status=$('#holdingStatus').value,q=$('#holdingSearch').value.toLowerCase();const rows=D.portfolioRegister.records.filter(r=>(group==='all'||group==='legal'&&['direct-subsidiary','vehicle-subsidiary','other-consolidated'].includes(r.group)||(group==='focus'?!['direct-subsidiary','vehicle-subsidiary','other-consolidated'].includes(r.group)||['moka','dkab','sbr','bintang_kecil','bridestory'].includes(r.id):r.group===group))&&(status==='all'||status==='current'&&['direct-subsidiary','vehicle-subsidiary','other-consolidated','associate'].includes(r.group)||status==='historical'&&(r.exitDate||['legacy-equity','fund-history','divested','bintang-equity'].includes(r.group))||status==='pending'&&!r.reviewed)&&[r.name,r.legalName,r.route,r.status].join(' ').toLowerCase().includes(q));$('#holdingRows').innerHTML=rows.map(compactHoldingRow).join('')||'<tr><td colspan="4">No matching positions. Adjust the route, status or company search.</td></tr>';$('#holdingCount').textContent=rows.length+' positions'};$('#holdingSearch').oninput=draw;$('#holdingGroup').onchange=draw;$('#holdingStatus').onchange=draw;draw();tabs.querySelectorAll('[data-position-tab]').forEach(b=>b.onclick=()=>{tabs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-selected',String(x===b)));for(const [id,p] of Object.entries(panels))p.hidden=id!==b.dataset.positionTab});}
