function orderedProfileSignals(name,news=[],id){const plain=name.split('(')[0].trim().toLowerCase();const signals=D.feed.filter(f=>id&&f.entityId===id||f.entity.toLowerCase()===plain||plain.length>4&&f.title.toLowerCase().includes(plain));const reviewed=signals.filter(f=>f.verified).slice(0,10),leads=signals.filter(f=>!f.verified).slice(0,8);return `<div class="signal-profile-head"><b>${reviewed.length} reviewed updates</b><span>${leads.length} discovery leads shown</span></div>${reviewed.length?reviewed.map(feedItem).join(''):'<div class="profile-empty"><b>No reviewed operating update matched</b><p>The position remains covered. Source headlines below require content review.</p></div>'}${leads.length?`<details class="signal-context discovery-details"><summary>News discovery · ${leads.length} leads · article review pending</summary>${leads.map(feedItem).join('')}</details>`:''}${!signals.length&&news.length?profileSection('Reference updates',news.slice(0,5).map(n=>`<div class="profile-news"><small>${esc(n.date)}</small><h3>${link(n.url,n.title)}</h3><p>${esc(n.implication||'Source review required.')}</p></div>`).join(''),'Older attributed reference research; current review pending.'):''}`}

