function businessSignal(f){return f.verified&&f.category!=='Portfolio diligence'&&!/^Review date/i.test(f.dateBasis||'')&&!/statement.review|roster.review|exit.review/.test(f.id||'')}
function capitalIntelligence(id){
  if(!['argor','argor-funds','bintang_kecil'].includes(id))return '';
  const fund=id!=='bintang_kecil';const group=fund?'fund-portfolio':'bintang-equity';
  const positions=D.portfolioRegister.records.filter(r=>r.group===group||(fund&&r.group==='fund-history'));
  const ids=new Set(positions.map(r=>r.id));const latest=D.feed.filter(f=>businessSignal(f)&&(ids.has(f.entityId)||positions.some(r=>r.name.toLowerCase()===f.entity.toLowerCase()))).slice(0,4);
  const facts=fund?[['Fund II size','US$240m','June 2023 · total fund, not GoTo commitment'],['Manager AUM','US$400m','2026 manager profile · not GoTo NAV'],['Manager portfolio','34 companies','2026 firm profile · examples mapped below']]:[['Effective GoTo ownership','99.99%','30 Jun 2026 · through SBR'],['Entity assets','Rp4.366bn','30 Jun 2026 · before consolidation eliminations'],['Historical investments','Xurya + Laku6','Reported exits; current residual stakes unresolved']];
  return `<section class="profile-section capital-intelligence"><h3>${fund?'Fund exposure and portfolio developments':'Corporate vehicle and historical investments'}</h3><div class="profile-metrics">${facts.map(([label,value,basis])=>`<div><small>${label}</small><b>${value}</b><p class="note">${basis}</p></div>`).join('')}</div><p>${fund?'GoTo’s economic interest is in the funds. Funding, operating milestones and governance at investees are monitoring inputs; cash distributions and NAV changes determine attributable return.':'The legal subsidiary remains in the June filing. The two historical investments cover solar projects and electronics recommerce; exit records prevent treating all subsequent company news as current GoTo investment performance.'}</p><div class="capital-company-list">${positions.slice(0,fund?12:4).map(r=>`<button data-ent="${r.id}" class="capital-company-item">${logo(r.id,r.name,1)}<span><b>${esc(r.name)}</b><small>${esc(byId[r.id]?.desc?.split('.')[0]||r.accounting)}</small><small>${esc(r.exitDate?'Reported exit · '+r.exitDate:r.status)}</small></span><span>↗</span></button>`).join('')}</div>${fund&&positions.length>12?'<details class="signal-context"><summary>Additional historical and reported portfolio positions ('+(positions.length-12)+')</summary><div class="capital-company-list">'+positions.slice(12).map(r=>'<button class="capital-company-item" data-ent="'+r.id+'">'+logo(r.id,r.name,1)+'<span><b>'+esc(r.name)+'</b><small>'+esc(r.status)+'</small></span></button>').join('')+'</div></details>':''}<h3 style="margin-top:22px">Underlying business updates</h3>${latest.length?latest.map(signalCompact).join(''):'<p class="note">No recent reviewed operating update matched. Open each company to inspect dated evidence and research leads.</p>'}<details class="signal-context"><summary>${fund?'What determines GoTo’s return':'What remains to reconcile'}</summary><p>${fund?'Fund I / II allocation, contributed capital, unfunded commitments, distributions, fees, carry and audited NAV are not publicly quantified. The manager roster and company fundraises cannot fill those fields.':'Confirm disposal proceeds and any retained shares or rights. The corporate vehicle’s assets are not a current Xurya or Laku6 valuation.'}</p></details></section>`;
}
