/* Ownership exploration shares the dashboard snapshot and company workspaces. */
const OWNERSHIP_SCOPES=[['overview','Overview'],['equity','Group equity'],['bintang','Bintang Kecil'],['fund','Argor funds'],['history','Historical positions'],['legal','Full legal register']];
const OWNERSHIP_COPY={
 overview:['The economic relationship comes first','Follow group vehicles, strategic associates and fund backing. Select a company for its stake basis, sources, news and diligence.'],
 equity:['Control and strategic equity','Current disclosed subsidiaries and associates. Percentages describe effective group ownership where reported, rather than each immediate holder’s stake.'],
 bintang:['A corporate vehicle, with historical investments','Bintang Kecil is disclosed through SBR. Xurya and Laku6 have reported exits; the network does not assume a retained stake or exit proceeds.'],
 fund:['GoTo backs funds; Argor manages them','Underlying companies are reported fund portfolio examples. Allocation to Fund I / II, GoTo’s capital account and attributable NAV are undisclosed.'],
 history:['Keep history separate from current exposure','These links need current holding confirmation. Reported exits and historical investments are not evidence of retained ownership or realized returns.'],
 legal:['The complete disclosed group inventory','51 subsidiaries and 11 other consolidated entities. Some disclosed intermediary groupings do not establish every immediate shareholder.']
};
function ownershipKind(edge){const t=(edge.type||'').toLowerCase();return /histor|legacy|exit|divested/.test(t)?'history':/fund/.test(t)?'fund':/associate/.test(t)?'associate':/other-consolidated/.test(t)?'control':'equity'}
function ownershipEligible(edge){return !/operating product|footprint|loyalty|vehicle;/.test(edge.type||'')}
function ownershipNodeLabel(id){const rec=D.portfolioRegister.records.find(r=>r.id===id);if(id==='goto')return 'Listed parent · IDX:GOTO';if(id==='argor')return 'Fund manager · ownership not implied';if(id==='argor-funds')return 'Fund backing · allocation undisclosed';if(rec?.exitDate)return 'Reported exit · '+rec.exitDate;if(rec?.stakePct!=null)return rec.stakePct+'% effective group stake';if(rec?.group==='fund-portfolio')return 'Fund portfolio example · stake undisclosed';if(rec?.group==='other-consolidated')return 'Consolidated · percentage not itemized';return rec?HOLDING_GROUPS[rec.group]||'Relationship under review':'Relationship under review'}
function ownershipAncestors(ids,edges){const result=new Set(ids);for(let i=0;i<12;i++){const n=result.size;for(const e of edges)if(result.has(e.to))result.add(e.from);if(result.size===n)break}return result}
function ownershipRecords(scope,query=''){
 const edges=D.eco.edges.filter(ownershipEligible),records=D.portfolioRegister.records;
 let ids;
 if(query){const q=query.toLowerCase();ids=records.filter(r=>[r.name,r.legalName,r.route].join(' ').toLowerCase().includes(q)).map(r=>r.id);if(/goto|go to/.test(q))ids.push('goto');}
 else if(scope==='overview')ids=['goto','dkab','sbr','rab','bintang_kecil','tokopedia','bank_jago','moka','midtrans','gopay','argor','argor-funds','electrum'];
 else if(scope==='equity')ids=records.filter(r=>['direct-subsidiary','vehicle-subsidiary','associate'].includes(r.group)&&byId[r.id]?.category!=='legal').map(r=>r.id);
 else if(scope==='bintang')ids=['goto','sbr','bintang_kecil','xurya','laku6'];
 else if(scope==='fund')ids=records.filter(r=>['fund-manager','fund-exposure','fund-portfolio'].includes(r.group)).map(r=>r.id);
 else if(scope==='history')ids=records.filter(r=>['legacy-equity','divested','fund-history','bintang-equity','unresolved-equity'].includes(r.group)).map(r=>r.id);
 else ids=records.filter(r=>['direct-subsidiary','vehicle-subsidiary','other-consolidated'].includes(r.group)).map(r=>r.id);
 const included=ownershipAncestors(ids,edges);included.add('goto');
 const nodes=E.filter(e=>included.has(e.id));
 const valid=new Set(nodes.map(e=>e.id));return {nodes,edges:edges.filter(e=>valid.has(e.from)&&valid.has(e.to)),matches:ids.length};
}
function ownershipLayout(nodes,edges){
 const ids=new Set(nodes.map(n=>n.id)),parents=new Map();
 // Pick a documented route for layout; every supplied relationship remains an edge.
 for(const e of edges){if(e.to==='goto')continue;const old=parents.get(e.to);if(!old||ownershipKind(old)==='history'&&ownershipKind(e)!=='history')parents.set(e.to,e)}
 const depths=new Map([['goto',0],['argor',1]]);
 const depth=(id,trail=new Set())=>{if(depths.has(id))return depths.get(id);if(trail.has(id))return 1;const p=parents.get(id);const d=p&&ids.has(p.from)?Math.min(5,1+depth(p.from,new Set([...trail,id]))):1;depths.set(id,d);return d};
 nodes.forEach(n=>depth(n.id));const columns=new Map();for(const n of nodes){const d=depths.get(n.id);if(!columns.has(d))columns.set(d,[]);columns.get(d).push(n)}
 const rank=id=>['goto','dkab','sbr','rab','argor','argor-funds','tokopedia','bank_jago','moka','midtrans','gopay','bintang_kecil','electrum'].indexOf(id);
 for(const [d,list] of [...columns].sort((a,b)=>a[0]-b[0]))list.sort((a,b)=>{if(d>1){const previous=columns.get(d-1)||[];const p1=previous.findIndex(n=>n.id===parents.get(a.id)?.from),p2=previous.findIndex(n=>n.id===parents.get(b.id)?.from);if(p1!==p2)return (p1<0?100:p1)-(p2<0?100:p2)}const r1=rank(a.id),r2=rank(b.id);return (r1<0?100:r1)-(r2<0?100:r2)||a.name.localeCompare(b.name)});
 const nodeWidth=222,nodeHeight=72,step=96,colStep=308,padding=30;
 const height=Math.max(360,...[...columns.values()].map(x=>x.length*step+82));const width=(Math.max(...columns.keys())+1)*colStep+padding;
 const positions=new Map();for(const [d,list] of columns){let offset=d===0?Math.min(180,height/2-36):70;list.forEach((n,i)=>positions.set(n.id,{x:padding+d*colStep,y:offset+i*step}))}
 return {positions,width,height,nodeWidth,nodeHeight,columns};
}
function vEco(){
 const sec=$('#v-ecosystem');sec.innerHTML=`<div class="ownership-intro"><div><span class="ownership-eyebrow">ECOSYSTEM INTELLIGENCE</span><h2>Understand the route. Know the exposure.</h2><p>One ownership network, connected to company evidence and operating signals.</p></div><a class="btn" href="#portfolio" data-register-open>Position register →</a></div>
 <div class="ownership-workspace card"><div class="ownership-scopes" role="group" aria-label="Ownership network scope">${OWNERSHIP_SCOPES.map(([id,name])=>`<button class="btn" data-ownership-scope="${id}" aria-pressed="${id==='overview'}">${name}</button>`).join('')}</div>
 <div class="ownership-heading"><div><h3 id="ownershipTitle"></h3><p class="note" id="ownershipDescription"></p></div><span id="ownershipCount" class="holding-badge"></span></div>
 <div class="ownership-tools"><label class="ownership-search">⌕ <input id="ownershipSearch" type="search" aria-label="Find a company in the ownership network" placeholder="Find company or legal entity…"></label><div class="ownership-zoom"><button class="btn" id="ownershipZoomOut" aria-label="Zoom out ownership network">−</button><output id="ownershipZoomLabel">100%</output><button class="btn" id="ownershipZoomIn" aria-label="Zoom in ownership network">+</button><button class="btn" id="ownershipFit">Fit width</button><button class="btn" id="ownershipReset">Reset</button><button class="btn" id="ownershipExpand" aria-pressed="false">Expand view</button></div></div>
 <div class="ownership-legend"><span class="equity">Group equity / disclosed control</span><span class="associate">Strategic associate</span><span class="fund">Fund / management relationship</span><span class="history">Historical / current stake unconfirmed</span></div>
 <div class="ownership-selection"><span id="ownershipSelected" role="status" aria-live="polite"></span><button class="btn" id="ownershipProfile" data-ent="goto">Company profile ↗</button></div>
 <div class="ownership-viewport" id="ownershipViewport" tabindex="0" aria-label="Ownership network. Scroll to explore; use zoom controls for scale."><div id="ownershipStage"></div></div>
 <p class="ownership-caption note">Select a node to highlight its connections. Scroll inside the network to explore. Dotted links preserve fund exposure and historical uncertainty; they do not imply direct equity.</p></div>
 <div id="ownershipDetails" class="ownership-details"></div>`;
 const state={scope:'overview',query:'',selected:'goto',zoom:1,layout:null,graph:null};
 function select(id){state.selected=id;const entity=byId[id],rec=D.portfolioRegister.records.find(r=>r.id===id);if(!entity)return;
  $('#ownershipSelected').textContent=entity.name+' · '+ownershipNodeLabel(id);$('#ownershipProfile').dataset.ent=id;
  const connected=new Set([id]);const ancestors=ownershipAncestors([id],state.graph.edges);ancestors.forEach(x=>connected.add(x));if(id==='goto')state.graph.nodes.forEach(n=>connected.add(n.id));state.graph.edges.forEach(e=>{if(e.from===id)connected.add(e.to)});
  sec.querySelectorAll('[data-network-node]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.networkNode===id));b.classList.toggle('network-neighbor',connected.has(b.dataset.networkNode));b.classList.toggle('network-muted',id!=='goto'&&!connected.has(b.dataset.networkNode))});
  sec.querySelectorAll('[data-network-from]').forEach(p=>p.classList.toggle('network-edge-active',connected.has(p.dataset.networkFrom)&&connected.has(p.dataset.networkTo)));
  const links=D.eco.edges.filter(ownershipEligible).filter(e=>e.from===id||e.to===id);
  const signalMatch=f=>f.entityId===id||id==='goto'&&f.entity==='GoTo'||id==='argor'&&f.entity==='Argor Capital'||f.entity?.toLowerCase()===entity.name.toLowerCase()||id==='bank_jago'&&/bank jago/i.test(f.entity||'')||id==='bintang_kecil'&&f.entity==='Bintang Kecil'||id==='argor-funds'&&/argor/i.test(f.entity||'');
  const news=D.feed.filter(f=>f.verified&&businessSignal(f)&&signalMatch(f)).slice(0,3);
  $('#ownershipDetails').innerHTML=`<section class="card ownership-detail-card"><div class="ownership-detail-heading">${logo(id,entity.name)}<div><span class="ownership-eyebrow">SELECTED POSITION</span><h3>${esc(entity.name)}</h3><small>${esc(rec?.legalName||entity.relation)}</small></div></div><p>${esc(entity.desc||entity.context?.role||'Open the company profile for available business context.')}</p><div class="ownership-facts"><div><small>Ownership / relationship</small><b>${esc(ownershipNodeLabel(id))}</b></div><div><small>Evidence vintage</small><b>${esc(rec?.asOf||links[0]?.asOf||'See source dates')}</b></div></div>${rec?`<p class="note"><b>Disclosed route:</b> ${esc(rec.route)}</p><p class="note"><b>Meaning:</b> ${esc(rec.why)}</p><details><summary>Stake basis and next check</summary><p>${esc(rec.stakeBasis)}</p><p>${esc(rec.monitor)}</p></details>`:'<p class="note">Manager relationships, fund backing and equity ownership are different economic interests.</p>'}<div class="ownership-detail-actions"><button class="btn" data-ent="${id}">Open full company workspace ↗</button>${link(rec?.sourceUrl||links[0]?.sourceUrl||entity.sources?.[0],'Source evidence ↗')}</div></section>
  <section class="card ownership-detail-card"><h3>Connections & decision signals</h3><div class="ownership-connections">${links.map(e=>{const other=e.from===id?e.to:e.from,n=byId[other];return n?`<button class="ownership-connection" data-network-related="${other}"><span>${e.from===id?'→':'←'} ${esc(n.name)}</span><small>${esc(e.type)}${e.stakePct!=null?' · '+e.stakePct+'% effective':''} · ${esc(e.asOf||'See source')}</small></button>`:''}).join('')||'<p class="note">No documented equity connection in the current snapshot.</p>'}</div><h4>What changed / why it matters</h4>${news.length?news.map(f=>`<div class="ownership-news"><small>${esc(f.date)} · ${esc(f.entity)}</small><b>${link(f.url,f.title)}</b><p>${esc(f.soWhat||f.implication||f.why||'Open the sourced update and company Signals for the decision context.')}</p></div>`).join(''):`<p class="note">No reviewed operating update matched this legal entity. ${rec?.monitor?esc(rec.monitor):'Use the full company workspace for source links and discovery leads.'}</p>`}</section>`;
  $('#ownershipDetails').querySelectorAll('[data-network-related]').forEach(b=>b.onclick=()=>{const target=b.dataset.networkRelated;if(!state.graph.nodes.some(n=>n.id===target)){state.query=byId[target]?.name||'';$('#ownershipSearch').value=state.query;draw()}select(target);scrollNode(target)});
 }
 function scale(){const l=state.layout;if(!l)return;const stage=$('#ownershipStage');$('#ownershipViewport').style.height=Math.min(570,Math.max(340,l.height*state.zoom+20))+'px';stage.style.width=l.width*state.zoom+'px';stage.style.height=l.height*state.zoom+'px';const canvas=stage.firstElementChild;if(canvas)canvas.style.transform=`scale(${state.zoom})`;$('#ownershipZoomLabel').textContent=Math.round(state.zoom*100)+'%';}
 function scrollNode(id){const pos=state.layout.positions.get(id);if(!pos)return;$('#ownershipViewport').scrollTo({left:Math.max(0,pos.x*state.zoom-100),top:Math.max(0,pos.y*state.zoom-120),behavior:'smooth'})}
 function draw(){const graph=ownershipRecords(state.scope,state.query);state.graph=graph;const layout=ownershipLayout(graph.nodes,graph.edges);state.layout=layout;
  $('#ownershipTitle').textContent=state.query?'Company search · connected routes':OWNERSHIP_COPY[state.scope][0];$('#ownershipDescription').textContent=state.query?(graph.matches?graph.matches+' matching positions plus their disclosed upstream connections.':'No positions match. Try a shorter company or legal-entity name.'):OWNERSHIP_COPY[state.scope][1];
  $('#ownershipCount').textContent=graph.nodes.length+' entities · '+graph.edges.length+' '+(graph.edges.length===1?'link':'links');
  sec.querySelectorAll('[data-ownership-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ownershipScope===state.scope&&!state.query)));
  const svg=graph.edges.map(e=>{const a=layout.positions.get(e.from),b=layout.positions.get(e.to),x1=a.x+layout.nodeWidth,y1=a.y+layout.nodeHeight/2,x2=b.x,y2=b.y+layout.nodeHeight/2;const kind=ownershipKind(e),cx=(x1+x2)/2;return `<path class="network-edge ${kind}" data-network-from="${esc(e.from)}" data-network-to="${esc(e.to)}" d="M${x1},${y1} C${cx},${y1} ${cx},${y2} ${x2},${y2}"><title>${esc(e.type)}${e.stakePct!=null?' · '+e.stakePct+'% effective group ownership':''} · ${esc(e.asOf||'See evidence')}</title></path>`}).join('');
  $('#ownershipStage').innerHTML=`<div class="ownership-canvas" style="width:${layout.width}px;height:${layout.height}px"><svg class="ownership-links" width="${layout.width}" height="${layout.height}" viewBox="0 0 ${layout.width} ${layout.height}" aria-hidden="true">${svg}</svg>${[...layout.columns.keys()].map(d=>`<span class="ownership-level" style="left:${30+d*308}px">${d===0?'LISTED GROUP':d===1?'VEHICLES & STRATEGIC LINKS':'CONNECTED ENTITIES · LEVEL '+d}</span>`).join('')}${graph.nodes.map(n=>{const p=layout.positions.get(n.id),edge=graph.edges.find(e=>e.to===n.id),kind=edge?ownershipKind(edge):n.id==='argor'?'fund':'equity';return `<button class="ownership-node ${kind}" data-network-node="${esc(n.id)}" style="left:${p.x}px;top:${p.y}px" aria-pressed="false" title="${esc(n.name)} · ${esc(ownershipNodeLabel(n.id))}">${logo(n.id,n.name,1)}<span><b>${esc(n.name)}</b><small>${esc(ownershipNodeLabel(n.id))}</small></span></button>`}).join('')}${state.query&&!graph.matches?'<div class="ownership-empty">No matching positions.<br>Clear your search to return to the network.</div>':''}</div>`;
  sec.querySelectorAll('[data-network-node]').forEach(b=>b.onclick=()=>select(b.dataset.networkNode));scale();if(!graph.nodes.some(n=>n.id===state.selected))state.selected='goto';select(state.selected);
 }
 sec.querySelectorAll('[data-ownership-scope]').forEach(b=>b.onclick=()=>{state.scope=b.dataset.ownershipScope;state.query='';state.selected=state.scope==='bintang'?'bintang_kecil':state.scope==='fund'?'argor-funds':'goto';state.zoom=1;$('#ownershipSearch').value='';draw();$('#ownershipViewport').scrollTo(0,0)});
 $('#ownershipSearch').oninput=()=>{state.query=$('#ownershipSearch').value.trim();draw();$('#ownershipViewport').scrollTo(0,0)};
 $('#ownershipZoomIn').onclick=()=>{state.zoom=Math.min(1.6,state.zoom+.15);scale()};$('#ownershipZoomOut').onclick=()=>{state.zoom=Math.max(.45,state.zoom-.15);scale()};
 $('#ownershipFit').onclick=()=>{state.zoom=Math.max(.45,Math.min(1,($('#ownershipViewport').clientWidth-24)/state.layout.width));scale();$('#ownershipViewport').scrollTo(0,0)};
 $('#ownershipReset').onclick=()=>{state.zoom=1;scale();$('#ownershipViewport').scrollTo(0,0)};
 $('#ownershipExpand').onclick=()=>{const expanded=sec.classList.toggle('ownership-expanded');$('#ownershipExpand').textContent=expanded?'Collapse view':'Expand view';$('#ownershipExpand').setAttribute('aria-pressed',String(expanded))};draw();
}

openEntity=openEntityExperience;
// Render charts only when their canvas approaches the viewport. The dashboard
// can open without downloading a chart library or contacting a third-party CDN.
let chartLibrary;
const chartQueue=new Map();
function loadChartLibrary(){
  if(window.Chart)return Promise.resolve(window.Chart);
  if(!chartLibrary)chartLibrary=new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='assets/chart.4.4.1.min.js';script.async=true;
    script.onload=()=>window.Chart?resolve(window.Chart):reject(new Error('Chart library unavailable'));
    script.onerror=()=>reject(new Error('Chart download failed'));
    document.head.appendChild(script);
  }).catch(error=>{chartLibrary=null;throw error});
  return chartLibrary;
}
async function paintQueuedChart(id){
  const job=chartQueue.get(id);if(!job||!job.el.isConnected)return;
  try{
    await loadChartLibrary();
    if(chartQueue.get(id)!==job||!job.el.isConnected)return;
    if(charts[id])charts[id].destroy();
    job.cfg.options=job.cfg.options||{};job.cfg.options.animation=false;
    charts[id]=new Chart(job.el,job.cfg);
    job.el.parentElement.querySelector('.chart-load-state')?.remove();
    chartQueue.delete(id);
  }catch(error){
    if(!job.el.isConnected)return;
    const state=job.el.parentElement.querySelector('.chart-load-state');
    if(state){state.textContent='Chart could not load. ';const retry=document.createElement('button');retry.className='btn';retry.textContent='Retry chart';retry.onclick=()=>{state.textContent='Loading chart…';paintQueuedChart(id)};state.appendChild(retry)}
  }
}
const chartObserver='IntersectionObserver' in window?new IntersectionObserver(entries=>{
  for(const entry of entries)if(entry.isIntersecting){chartObserver.unobserve(entry.target);const job=chartQueue.get(entry.target.id);if(job?.el===entry.target)paintQueuedChart(entry.target.id)}
},{rootMargin:'180px'}):null;
function chart(id,cfg){
  const el=document.getElementById(id);if(!el)return;
  const parent=el.parentElement;parent.style.position='relative';
  if(!parent.querySelector('.chart-load-state')){const state=document.createElement('div');state.className='chart-load-state';state.setAttribute('role','status');state.textContent='Loading chart…';parent.appendChild(state)}
  chartQueue.set(id,{el,cfg});
  if(chartObserver)chartObserver.observe(el);else paintQueuedChart(id);
}

async function prepareCurrentCharts(){
  const source=$('#drawer.on #dpanel')||$('section.view.on');
  await Promise.all([...chartQueue].filter(([,job])=>source?.contains(job.el)).map(([id])=>paintQueuedChart(id)));
}

